function expectStaticAppUrl (hearthApp) {
    const hearthDomain = conf['HEARTH_DOMAIN']
    const hearthUrl = new URL(hearthDomain)
    const hostnameParts = hearthUrl.hostname.split('.')
    const domainSuffix = hostnameParts.length > 2 ? hostnameParts.slice(1) : hostnameParts
    const appHostname = [hearthApp.id, 'miniapps-static', ...domainSuffix].join('.')
    const port = hearthUrl.port

    const appUrl = `${hearthUrl.protocol}//${appHostname}${port ? `:${port}` : ''}`

    expect(hearthApp).toHaveProperty('appUrl', appUrl)
}

async function createApprovedB2CAppPublishRequest (supportClient, app) {
    const [request] = await createTestB2CAppPublishRequest(supportClient, app, {
        isAppTested: true,
        isContractSigned: true,
        isInfoApproved: true,
        status: PUBLISH_REQUEST_APPROVED_STATUS,
    })
    return request
}

